const posts = $input.all().map(i => i.json);
const last7 = posts.slice(-14); // last 14 rows = ~week of data across platforms

const withEngagement = last7.map(p => {
  const impressions = parseInt(p['Impressions'] || p['Reach'] || 1);
  const likes = parseInt(p['Likes'] || 0);
  const comments = parseInt(p['Comments'] || 0);
  const shares = parseInt(p['Shares'] || p['Reposts'] || 0);
  const saves = parseInt(p['Saves'] || 0);
  const totalEngagements = likes + comments * 3 + shares * 5 + saves * 2; // weighted
  const engRate = impressions > 0 ? ((totalEngagements / impressions) * 100).toFixed(2) : 0;
  return { ...p, engagement_rate: parseFloat(engRate), total_engagements: totalEngagements, impressions };
});

const byPlatform = {};
withEngagement.forEach(p => {
  const plat = p['Platform'] || 'Unknown';
  if (!byPlatform[plat]) byPlatform[plat] = [];
  byPlatform[plat].push(p);
});

const platformSummary = Object.entries(byPlatform).map(([plat, posts]) => ({
  platform: plat,
  avg_engagement_rate: (posts.reduce((s,p)=>s+p.engagement_rate,0)/posts.length).toFixed(2),
  top_post: posts.sort((a,b)=>b.engagement_rate-a.engagement_rate)[0]
}));

const topPost = withEngagement.sort((a,b) => b.engagement_rate - a.engagement_rate)[0];
const worstPost = withEngagement.sort((a,b) => a.engagement_rate - b.engagement_rate)[0];

return [{ json: { posts: withEngagement, platform_summary: platformSummary, top_post: topPost, worst_post: worstPost, total_posts: withEngagement.length } }];

const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const analysis = JSON.parse(raw);
return [{ json: { ...analysis, metrics: $('Calculate Engagement Metrics').item.json } }];

